import{_ as o,c,o as s,aj as a}from"./chunks/framework.BlveriQe.js";const h=JSON.parse('{"title":"Interface: DocumentAccessResult","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentAccessResult.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentAccessResult.md"}'),t={name:"reference/js-bao-wss-client/api/interfaces/DocumentAccessResult.md"};function r(n,e,d,i,l,u){return s(),c("div",null,[...e[0]||(e[0]=[a('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentAccessResult</p><h1 id="interface-documentaccessresult" tabindex="-1">Interface: DocumentAccessResult <a class="header-anchor" href="#interface-documentaccessresult" aria-label="Permalink to “Interface: DocumentAccessResult”">​</a></h1><p>Result of <code>documents.validateAccess()</code>, describing whether a user can access the document and at what permission level — the current user by default, or the user named by <code>{ userId }</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="accesssource" tabindex="-1">accessSource? <a class="header-anchor" href="#accesssource" aria-label="Permalink to “accessSource?”">​</a></h3><blockquote><p><code>optional</code> <strong>accessSource?</strong>: <code>&quot;owner&quot;</code> | <code>&quot;link&quot;</code> | <code>&quot;grant&quot;</code> | <code>&quot;group&quot;</code></p></blockquote><p>How the access was obtained, present whenever <code>hasAccess</code> is true. The same vocabulary <code>documents.get()</code> reports.</p><hr><h3 id="approle" tabindex="-1">appRole? <a class="header-anchor" href="#approle" aria-label="Permalink to “appRole?”">​</a></h3><blockquote><p><code>optional</code> <strong>appRole?</strong>: <code>&quot;owner&quot;</code> | <code>&quot;admin&quot;</code> | <code>&quot;member&quot;</code></p></blockquote><p>The SUBJECT&#39;s role in the app, present only when a <code>userId</code> was named.</p><p>Reported beside <code>permission</code>, never folded into it: the tag routes admit an <code>admin</code> or <code>owner</code> without a document grant, and content writes (<code>documents.update()</code>, block and blob writes) admit nobody without one. A caller gating a content write must decide on <code>permission</code> alone.</p><hr><h3 id="error" tabindex="-1">error? <a class="header-anchor" href="#error" aria-label="Permalink to “error?”">​</a></h3><blockquote><p><code>optional</code> <strong>error?</strong>: <code>string</code></p></blockquote><hr><h3 id="hasaccess" tabindex="-1">hasAccess <a class="header-anchor" href="#hasaccess" aria-label="Permalink to “hasAccess”">​</a></h3><blockquote><p><strong>hasAccess</strong>: <code>boolean</code></p></blockquote><hr><h3 id="permission" tabindex="-1">permission? <a class="header-anchor" href="#permission" aria-label="Permalink to “permission?”">​</a></h3><blockquote><p><code>optional</code> <strong>permission?</strong>: <code>&quot;owner&quot;</code> | <code>&quot;read-write&quot;</code> | <code>&quot;reader&quot;</code> | <code>&quot;admin&quot;</code></p></blockquote><hr><h3 id="success" tabindex="-1">success <a class="header-anchor" href="#success" aria-label="Permalink to “success”">​</a></h3><blockquote><p><strong>success</strong>: <code>boolean</code></p></blockquote>',26)])])}const m=o(t,[["render",r]]);export{h as __pageData,m as default};
